import{_ as e,o,c as d,a4 as a}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"CLI Reference","description":"","frontmatter":{},"headers":[],"relativePath":"cli/index.md","filePath":"cli/index.md","lastUpdated":null}'),i={name:"cli/index.md"};function r(c,t,l,s,n,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><p>The SFCC Campaign Automation CLI is split into two command sets:</p><ul><li><strong>Producer Commands</strong> — the daily workflow for web producers</li><li><strong>Dev Commands</strong> — power tools for the web developer</li></ul><h2 id="producer-commands" tabindex="-1">Producer Commands <a class="header-anchor" href="#producer-commands" aria-label="Permalink to &quot;Producer Commands&quot;">​</a></h2><p>These commands handle the entire daily flow. Most use the <a href="/ocapi-docs.github.io/cli/select.html">sticky date</a> automatically.</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><a href="/ocapi-docs.github.io/cli/pull.html"><code>pull</code></a></td><td>Git sync + fetch data + status dashboard + date prompt</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/select.html"><code>select</code></a></td><td>Set or switch the working date (sticky)</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/build.html"><code>build</code></a></td><td>Generate HTML + OCAPI payload (guarded)</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/refresh.html"><code>edit</code></a></td><td>Force-rebuild after template edits</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/preview.html"><code>preview</code></a></td><td>Compose multi-zone preview + show links</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/push.html"><code>push</code></a></td><td>Validate data quality + sync to SFCC staging</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/replicate.html"><code>replicate</code></a></td><td>Manual STG → POD replication checklist</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/done.html"><code>done</code></a></td><td>Verify sync + generate changeout email</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/status.html"><code>status</code></a></td><td>Unified dashboard (live, ready, build, new)</td></tr></tbody></table><h2 id="dev-commands" tabindex="-1">Dev Commands <a class="header-anchor" href="#dev-commands" aria-label="Permalink to &quot;Dev Commands&quot;">​</a></h2><p>Configuration, testing, registry management, and advanced operations.</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><a href="/ocapi-docs.github.io/cli/setup.html"><code>setup</code></a></td><td>Interactive configuration wizard</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/upload.html"><code>upload</code></a></td><td>Partial sync — push only HTML changes (hotfix)</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/delete.html"><code>delete</code></a></td><td>Remove a refresh from SFCC and local files</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/registry.html"><code>registry</code></a></td><td>Manage the asset registry</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/reports.html"><code>reports</code></a></td><td>Statistics, coverage, and date reports</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/email.html"><code>email</code></a></td><td>Generate changeout email (standalone)</td></tr><tr><td><a href="/ocapi-docs.github.io/cli/health.html"><code>health</code></a></td><td>Check SFCC OCAPI connection</td></tr></tbody></table><h2 id="how-commands-route" tabindex="-1">How Commands Route <a class="header-anchor" href="#how-commands-route" aria-label="Permalink to &quot;How Commands Route&quot;">​</a></h2><p>All make commands call the unified CLI router at <code>src/cli/index.js</code>, which:</p><ol><li>Resolves the brand from config or <code>BRAND=</code> argument</li><li>Parses flags into an options object</li><li>Initializes a <code>BrandContext</code> (composition root)</li><li>Dispatches to the appropriate handler in <code>src/cli/commands/</code></li></ol><h2 id="common-options" tabindex="-1">Common Options <a class="header-anchor" href="#common-options" aria-label="Permalink to &quot;Common Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--force</code></td><td>Bypass build guards, force regeneration</td></tr><tr><td><code>--dry-run</code></td><td>Show what would change without making changes</td></tr><tr><td><code>--date=YYYY-MM-DD</code></td><td>Override sticky date for this command</td></tr><tr><td><code>--yes</code> / <code>-y</code></td><td>Skip confirmation prompts</td></tr><tr><td><code>DATE=</code></td><td>Makefile variable — same as <code>--date=</code></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Guide</a> — Daily guide</li><li><a href="/ocapi-docs.github.io/reference/commands.html">Commands Reference</a> — Full make command list</li><li><a href="/ocapi-docs.github.io/reference/architecture.html">Architecture</a> — System design</li></ul>',16)])])}const p=e(i,[["render",r]]);export{u as __pageData,p as default};
